var items = $props.items || []
var current = $props.value
var activeColor = $props.activeColor || $color.primary
var inactiveColor = $props.inactiveColor || '#606266'
return items.map(function (it) {
  var key = it == null ? '' : String(it.key != null ? it.key : '')
  var active = key === String(current != null ? current : '')
  var label = it == null || it.label == null ? '' : String(it.label)
  if (it != null && it.count != null && it.count !== '') {
    label = label + ' ' + it.count
  }
  return {
    key: key,
    label: label,
    active: active,
    textColor: active ? activeColor : inactiveColor
  }
})
